def solution(node):
    if not node:
        return None
    class Node:
        def __init__(self, val=0, neighbors=None):
            self.val = val
            self.neighbors = neighbors if neighbors is not None else []
    cloned = {}
    def dfs(curr):
        if curr in cloned:
            return cloned[curr]
        copy = Node(curr.val)
        cloned[curr] = copy
        for n in curr.neighbors:
            copy.neighbors.append(dfs(n))
        return copy
    return dfs(node)
